# Generates artifacts.manifest.json from the reviewed P01 inputs (parity/baselines/*/inputs.md, zccache.md).
# Every hash below is a value those files record; nothing here fetches anything.
# Usage: pwsh -File New-AapManifest.ps1 [-OutPath <file>]   (default: artifacts.manifest.json beside this script)
param([string]$OutPath = (Join-Path $PSScriptRoot 'artifacts.manifest.json'))
Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

$win = 'windows-2025-vs2026-x64'
$ubu = 'ubuntu-24.04-x64'
$winInputs = 'parity/baselines/windows-2025-vs2026-x64/inputs.md, "Version- or hash-pinned values"'
$ubuInputs = 'parity/baselines/ubuntu-24.04-x64/inputs.md, "Version- or hash-pinned values"'
$zccRef = 'parity/baselines/zccache.md, "Release assets"'
$ghHosts = @('release-assets.githubusercontent.com', 'objects.githubusercontent.com')
$zcc = 'https://github.com/zackees/zccache/releases/download/1.15.6/'

function Retry($timeout) { [ordered]@{ max_attempts = 3; backoff_seconds = 5; timeout_seconds = $timeout } }
function Lic($class, $redist, $note) { [ordered]@{ class = $class; redistribution = $redist; note = $note } }
function Entry($name, $version, $profiles, $file, $url, $redirect, $algo, $source, $value, $upEntry, $upKey, $size, $max, $types, $lic, $timeout, $ref, $note) {
    $e = [ordered]@{
        name = $name; version = $version; profiles = @($profiles); file_name = $file; urls = @($url); redirect_hosts = @($redirect)
        hash = [ordered]@{ algorithm = $algo; source = $source; value = $(if ($value) { $value.ToLowerInvariant() } else { $null }); upstream_entry = $upEntry; upstream_key = $upKey }
        size_bytes = $size; size_max_bytes = $max; content_types = @($types); license = $lic; retry = (Retry $timeout); evidence_ref = $ref
    }
    if ($note) { $e['note'] = $note }
    $e
}
function Blocker($id, $name, $profiles, $kind, $reason, $action, $ref) {
    [ordered]@{ id = $id; name = $name; profiles = @($profiles); blocker_kind = $kind; reason = $reason; owner_action = $action; evidence_ref = $ref }
}
function Zcc($file, $profile, $sha, $size) {
    Entry ('zccache-' + ($file -replace '^zccache-v1\.15\.6-', '' -replace '\.(tar\.gz|zip)$', '')) '1.15.6' @($profile) $file ($zcc + $file) $ghHosts 'sha256' 'upstream-file' $sha 'zccache-sha256sums' $file $size 104857600 @('application/octet-stream') (Lic 'unknown' 'unknown' 'Licence not recorded by P01; record it before the archive is placed in an image or redistributed.') 900 $zccRef 'Pinned value cross-checked against the SHA256SUMS entry of the same release; both must agree.'
}

$entries = @(
    (Entry 'zccache-sha256sums' '1.15.6' @($win, $ubu) 'SHA256SUMS' ($zcc + 'SHA256SUMS') $ghHosts 'sha256' 'literal' '6b5c2b96c99ab876814cedf3c6c1801d80dc2491fb823fcd8b58f3662c0231c3' $null $null 1636 65536 @('application/octet-stream', 'text/plain') (Lic 'unknown' 'unknown' 'Release metadata file of zackees/zccache.') 120 $zccRef 'Its first line hashes itself as the empty string; consumers skip that line. Transport integrity only, not a signature.')
    (Zcc 'zccache-v1.15.6-x86_64-unknown-linux-musl.tar.gz' $ubu '885a109c758808480ebda6b92ac0c55ae55ff2638f0ef850423bb185f28e59f7' 12389072)
    (Zcc 'zccache-v1.15.6-x86_64-unknown-linux-musl-debug.tar.gz' $ubu '6eccf0034b23df2fa9f6f523e43a5c2335847e6eb956de8b2e2a284651afaecd' 29806744)
    (Zcc 'zccache-v1.15.6-x86_64-pc-windows-msvc.zip' $win 'a9e2b079946d00757a56fea3dacd8a47f9cb4bcbfe8c427ffd719ced59fd949b' 10545387)
    (Zcc 'zccache-v1.15.6-x86_64-pc-windows-msvc-debug.zip' $win '619e41467ea832454c0a5fa8ab009497274279f8bbfe8ad4a39bc18784901ceb' 34900341)
    (Entry 'android-commandlinetools-win' '13114758' @($win) 'commandlinetools-win-13114758_latest.zip' 'https://dl.google.com/android/repository/commandlinetools-win-13114758_latest.zip' @() 'sha256' 'literal' '98B565CB657B012DAE6794CEFC0F66AE1EFB4690C699B78A614B4A6A3505B003' $null $null $null 268435456 @('application/zip') (Lic 'proprietary-eula' 'restricted' 'Android SDK terms; the scripts also write the SDK licence acceptances, which the operator inherits.') 1800 $winInputs 'The file name contains "latest" but the version is the build number 13114758 and the hash pins the content.')
    (Entry 'mysql-vcredist-x64' 'h20e2645b7cd5' @($win) 'vcredist_x64.exe' 'https://download.microsoft.com/download/0/5/6/056dcda9-d667-4e27-8001-8a0c6971d6b1/vcredist_x64.exe' @() 'sha256' 'literal' '20E2645B7CD5873B1FA3462B99A665AC8D6E14AAE83DED9D875FEA35FFDD7D7E' $null $null $null 33554432 @('application/octet-stream') (Lic 'vendor-redistributable' 'restricted' 'Microsoft Visual C++ redistributable; redistributable under Microsoft terms, record them before shipping inside an image.') 300 $winInputs 'Helper for the MySQL CLI install; the literal SHA-256 is committed upstream in Install-MysqlCli.ps1. Upstream records no version, so the version label is the first 12 hex digits of the hash behind an h; the hash is the identity.')
    (Entry 'docker-ce-install-helper' '8ea2a92d8dfa7815abcf5cc44a756a0ac3d0f513' @($win) 'install-docker-ce.ps1' 'https://raw.githubusercontent.com/microsoft/Windows-Containers/8ea2a92d8dfa7815abcf5cc44a756a0ac3d0f513/helpful_tools/Install-DockerCE/install-docker-ce.ps1' @() 'sha256' 'first-fetch' $null $null $null $null 1048576 @('text/plain') (Lic 'unknown' 'unknown' 'Licence of microsoft/Windows-Containers not recorded by P01.') 120 $winInputs 'Pinned to a commit, no upstream hash. Download needs -RecordFirstFetch and is recorded unverified. Data only: never executed by this tooling.')
    (Entry 'libicu70' '70.1-2' @($ubu) 'libicu70_70.1-2_amd64.deb' 'https://archive.ubuntu.com/ubuntu/pool/main/i/icu/libicu70_70.1-2_amd64.deb' @() 'sha512' 'literal' 'a6315482d93606e375c272718d2458870b95e4ed4b672ea8640cf7bc2d2c2f41aea13b798b1e417e1ffc472a90c6aad150d3d293aa9bddec48e39106e4042807' $null $null $null 33554432 @('application/vnd.debian.binary-package') (Lic 'open-source' 'allowed' 'ICU and Unicode licences.') 300 $ubuInputs 'SHA-512 as committed in configure-dpkg.sh upstream.')
    (Entry 'containernetworking-plugins' '1.1.1+ds1-3build1' @($ubu) 'containernetworking-plugins_1.1.1+ds1-3build1_amd64.deb' 'https://archive.ubuntu.com/ubuntu/pool/universe/g/golang-github-containernetworking-plugins/containernetworking-plugins_1.1.1+ds1-3build1_amd64.deb' @() 'sha256' 'first-fetch' $null $null $null $null 33554432 @('application/vnd.debian.binary-package') (Lic 'open-source' 'allowed' 'Apache-2.0 per the Debian package; confirm at first fetch.') 300 $ubuInputs 'No upstream hash seen. Needs -RecordFirstFetch; recorded unverified.')
    (Entry 'android-commandlinetools-linux' '11076708' @($ubu) 'commandlinetools-linux-11076708_latest.zip' 'https://dl.google.com/android/repository/commandlinetools-linux-11076708_latest.zip' @() 'sha256' 'first-fetch' $null $null $null $null 268435456 @('application/zip') (Lic 'proprietary-eula' 'restricted' 'Android SDK terms.') 1800 $ubuInputs 'Toolset gives the file name without a hash. URL derived from the Windows pin path on the same host and answered with HTTP 200 on 2026-10-19 (headers only). Needs -RecordFirstFetch.')
)

$blockers = @(
    (Blocker 'azure-base-image-windows-server-2025' 'Azure Marketplace image MicrosoftWindowsServer:WindowsServer:2025-Datacenter-g2' @($win) 'cloud-base-image' 'Exists only in Azure with the Azure agent and drivers. A local Hyper-V guest built from other media is a different base.' 'Decide the accepted deviation for the local base; the reference image stays the hosted runner.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 1")
    (Blocker 'windows-server-2025-media' 'Windows Server 2025 installation media and activation' @($win) 'licensed-media' 'Lawful media, edition, key or volume activation and the lab licence are owner decisions. The tooling never downloads, stores or redistributes it.' 'Owner supplies the Windows Server 2025 Evaluation ISO manually, records its SHA-256, edition and the evaluation licence terms, and places it outside the staging tree.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 2")
    (Blocker 'windows-updates-level' 'Windows Updates level of image build 10.0.26100.33438' @($win) 'moving-layout' 'Microsoft supersedes updates; the KB list is not recorded upstream.' 'Record the catalog state at the first lawful fetch or accept a documented update-level deviation.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 3")
    (Blocker 'visual-studio-2026-bootstrapper' 'Visual Studio 2026 Enterprise bootstrapper and stable channel (aka.ms/vs/postGRO-stable/vs_Enterprise.exe)' @($win) 'moving-layout' 'Channel stable has no pinned layout and serves the current build, not 18.10.12224.181. Entitlement for a non-GitHub host is not established.' 'Owner decides the entitlement, then a layout is created once and retained with a recorded hash; a layout creation is a separate approved step.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 4")
    (Blocker 'visual-studio-marketplace-extensions' 'Visual Studio Marketplace extensions (SSIS, Analysis Services, Reports, Installer Projects, Service Fabric, WiX)' @($win) 'proprietary-license' 'Downloaded by marketplace item name with no hash and their own terms.' 'Record licence terms and retain the VSIX files with hashes at the first lawful fetch.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 4")
    (Blocker 'windows-sdk-and-wdk' 'Windows 11 SDK 10.0.26100 and Windows Driver Kit (go.microsoft.com/fwlink redirects)' @($win) 'vendor-latest-no-hash' 'Fetched through vendor redirects with an Authenticode check only; Microsoft-licensed.' 'Resolve the redirect once, retain the installer and record hash and licence.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 5")
    (Blocker 'windows-vendor-latest-feeds' 'Vendor latest feeds without a hash source (Cosmos DB emulator, DacFx, SQL OLE DB, Chrome, Edge, Firefox, Selenium, Miniconda, MSYS2, MongoDB, ghcup and others)' @($win) 'vendor-latest-no-hash' 'The installed versions are recorded only in the upstream Readme; the feeds serve whatever is current.' 'Retain the exact installer files at the first lawful fetch with hash, URL chain and licence, or accept a documented drift.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 6")
    (Blocker 'windows-chocolatey-community-feed' 'Chocolatey community feed packages' @($win) 'vendor-latest-no-hash' 'Package versions resolve at build time from a moving feed.' 'Pin exact package versions and retain the nupkg files with hashes.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, table rows 6 and 17 to 22")
    (Blocker 'windows-service-fabric-runtime-sdk' 'Service Fabric runtime 11.7.157.1 and SDK 8.7.157' @($win) 'resolve-before-use' 'Checksums are pinned in the toolset but the download file names are built inside Install-ServiceFabricSDK.ps1, which P01 did not store.' 'Read the script at the pinned build commit, add the two entries with the toolset SHA-256 values.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, pinned values")
    (Blocker 'windows-docker-engine-compose' 'Docker Engine 29.7.2 and Docker Compose 2.40.3 (Windows)' @($win) 'resolve-before-use' 'Exact versions are pinned in the toolset; file URLs and hashes are not stored by P01.' 'Resolve the exact release files at the pinned build commit and add entries with a recorded hash.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, pinned values")
    (Blocker 'tool-cache-manifests' 'Tool cache version manifests (actions/python-versions, node-versions, go-versions, PyPy)' @($win, $ubu) 'moving-layout' 'The manifests live on main branches and move; newer versions already exist upstream.' 'Snapshot each manifest at a recorded commit, then pin the tool archives it lists by hash.' "parity/baselines/windows-2025-vs2026-x64/inputs.md, Drift since the pin")
    (Blocker 'azure-base-image-ubuntu-24.04' 'Azure Marketplace image canonical:ubuntu-24_04-lts:server (version latest at build)' @($ubu) 'cloud-base-image' 'Moves with every build and carries an Azure kernel and the Azure Linux agent. The base build date is not recorded.' 'Decide the accepted deviation for the local base image.' "parity/baselines/ubuntu-24.04-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 1")
    (Blocker 'ubuntu-superseded-apt-versions' 'Exact apt package versions listed in the upstream Readme' @($ubu) 'superseded-versions' 'The live archive keeps only current versions; availability of a snapshot service for these dates is not verified.' 'Retain the .deb files or an archive snapshot at the first lawful fetch.' "parity/baselines/ubuntu-24.04-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 2")
    (Blocker 'ubuntu-vendor-apt-repositories' 'Vendor package repositories added during the build (Microsoft, Docker, PostgreSQL, Google Cloud, Adoptium, Kubernetes, git-lfs)' @($ubu) 'vendor-repository' 'Configuration is removed after the build, versions are not archived and signing keys are fetched at build time.' 'Pin repository snapshots or retain packages with hashes and record the key fingerprints.' "parity/baselines/ubuntu-24.04-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 3")
    (Blocker 'ubuntu-proprietary-components' 'Proprietary or separately licensed components (Google Chrome, Edge, Microsoft packages, Android SDK, Docker Engine, MySQL)' @($ubu) 'proprietary-license' 'Licence terms and redistribution limits are not recorded; the scripts export ACCEPT_EULA globally.' 'Record licence terms and redistribution class per component before any acquisition.' "parity/baselines/ubuntu-24.04-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 4")
    (Blocker 'ubuntu-vendor-latest-feeds' 'Vendor latest feeds without a hash source (AWS CLI, azcopy, kubectl stable.txt, Helm, Pulumi, Packer, Miniconda, nvm, rustup, Composer, Gradle, Julia and others)' @($ubu) 'vendor-latest-no-hash' 'The versions installed on 2026-10-12 are recorded only in the upstream Readme.' 'Retain the exact files at the first lawful fetch with hash, URL chain and licence.' "parity/baselines/ubuntu-24.04-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 5")
    (Blocker 'ubuntu-floating-container-images' 'Six ghcr.io images pulled as :latest' @($ubu) 'floating-container' 'No digests were recorded upstream and the tags move.' 'Resolve each tag to a digest once and pin the digest.' "parity/baselines/ubuntu-24.04-x64/inputs.md, NEEDS EXTERNAL AUTHORIZATION 6")
    (Blocker 'ubuntu-docker-cmake-toolset-pins' 'Docker 28.0.4, Docker Compose 2.38.2 and CMake 3.31.6 (Ubuntu)' @($ubu) 'resolve-before-use' 'Exact versions are pinned in the toolset; file URLs and hashes are not stored by P01.' 'Resolve the exact release files at the pinned build commit and add entries with a recorded hash.' "parity/baselines/ubuntu-24.04-x64/inputs.md, pinned values")
)

$manifest = [ordered]@{
    schema = 1
    generated_from = 'parity/baselines/windows-2025-vs2026-x64/inputs.md, parity/baselines/ubuntu-24.04-x64/inputs.md, parity/baselines/zccache.md (P01, checked 2026-10-19)'
    entries = $entries
    not_reproducible = $blockers
}
$text = (ConvertTo-Json -InputObject $manifest -Depth 8) -replace "`r`n", "`n"
[IO.File]::WriteAllText($OutPath, $text + "`n", (New-Object System.Text.UTF8Encoding($false)))
